"use client";

import {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  type FocusEvent,
  type ReactNode,
} from "react";
import { useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { BJORK_PALETTE, type BjorkTone } from "@/components/bjork-ui/_core/palette";
import { useBjorkTone } from "@/components/bjork-ui/_core/tone";
import { useVisibleLoop } from "@/components/bjork-ui/_core/loop";
import { useElementSize } from "@/components/bjork-ui/_core/canvas";
import { resamplePath } from "@/components/bjork-ui/_core/path";
import { hashString, mulberry32 } from "@/components/bjork-ui/_core/random";

export interface ElasticFrameHandle {
  /** Pulls the string outward near `at` (0 to 1 along the outline) by `strength` px and lets it ring. */
  pluck: (at: number, strength?: number) => void;
}

export interface ElasticFrameProps {
  /** Content. Its corner radius should be `radius - padding / 2` so it sits concentric with the frame. */
  children?: ReactNode;
  radius?: number;
  points?: number;
  stiffness?: number;
  coupling?: number;
  damping?: number;
  pluckDistance?: number;
  maxStretch?: number;
  strokeWidth?: number;
  glow?: boolean;
  glowColor?: string;
  padding?: number;
  tone?: BjorkTone;
  attract?: boolean;
  /** Posed state: one frozen displaced frame with no loop. Used by preview captures. */
  debugState?: { at: number; amount: number };
  className?: string;
}

// The outline sits 12px inside the root. Half-pixel values keep the 1.5px straight runs crisp.
const INSET = 12.5;
const SUBSTEP = 1 / 240;
const GRAB_ARC = 40;
const GRAB_SIGMA = 18;
const GRAB_GAIN = 400;
const PLUCK_SIGMA = 22;
const POSE_SIGMA = 56;
const BREATH_IMPULSE = 110;
const ATTRACT_INTERVAL = 2800;
const ATTRACT_IDLE = 4000;
const ATTRACT_STRENGTH = 30;
const DEFAULT_PLUCK = 24;
const IDLE_EPS = 0.05;
const GLOW_WIDTH = 6;
const GLOW_ALPHA = 0.18;

type RGB = [number, number, number];

interface Colors {
  rest: RGB;
  ink: RGB;
}

interface Outline {
  width: number;
  height: number;
  count: number;
  rest: Float32Array;
  normal: Float32Array;
  spacing: number;
  // Dense render outline: the simulation runs on `count` points, painting uses `renderCount`.
  restPath: string;
  renderCount: number;
  renderRest: Float32Array;
  renderNormal: Float32Array;
}

interface Sim {
  o: Float32Array;
  v: Float32Array;
  acc: Float32Array;
  pts: Float32Array;
}

interface Grab {
  j: number;
  s: number;
}

interface Params {
  stiffness: number;
  coupling: number;
  damping: number;
  maxStretch: number;
  pluckDistance: number;
}

interface Bounds {
  left: number;
  top: number;
  sx: number;
  sy: number;
}

function roundedRectPath(x0: number, y0: number, x1: number, y1: number, r: number): string {
  return [
    `M${x0 + r} ${y0}`,
    `H${x1 - r}`,
    `A${r} ${r} 0 0 1 ${x1} ${y0 + r}`,
    `V${y1 - r}`,
    `A${r} ${r} 0 0 1 ${x1 - r} ${y1}`,
    `H${x0 + r}`,
    `A${r} ${r} 0 0 1 ${x0} ${y1 - r}`,
    `V${y0 + r}`,
    `A${r} ${r} 0 0 1 ${x0 + r} ${y0}`,
    "Z",
  ].join(" ");
}

// Outward unit normals for a closed loop of interleaved points.
function outwardNormals(points: Float32Array, count: number): Float32Array {
  const normal = new Float32Array(count * 2);
  for (let i = 0; i < count; i++) {
    const prev = (i - 1 + count) % count;
    const next = (i + 1) % count;
    const tx = points[next * 2] - points[prev * 2];
    const ty = points[next * 2 + 1] - points[prev * 2 + 1];
    const len = Math.hypot(tx, ty) || 1;
    // Clockwise in screen space, so (ty, -tx) points outward.
    normal[i * 2] = ty / len;
    normal[i * 2 + 1] = -tx / len;
  }
  return normal;
}

// Rest outline: equal arc-length samples plus outward unit normals, all in root coordinates.
function buildOutline(width: number, height: number, radius: number, count: number): Outline | null {
  if (width < 40 || height < 40) return null;
  const x0 = INSET;
  const y0 = INSET;
  const x1 = width - INSET;
  const y1 = height - INSET;
  const r = Math.max(0, Math.min(radius, (x1 - x0) / 2, (y1 - y0) / 2));
  const perimeter = 2 * (x1 - x0 - 2 * r) + 2 * (y1 - y0 - 2 * r) + 2 * Math.PI * r;
  const restPath = roundedRectPath(x0, y0, x1, y1, r);

  // The sampler returns count + 1 points; the last one repeats the first.
  const sampled = resamplePath(restPath, count + 1);
  const rest = new Float32Array(count * 2);
  for (let i = 0; i < count; i++) {
    rest[i * 2] = sampled[i * 2];
    rest[i * 2 + 1] = sampled[i * 2 + 1];
  }
  const normal = outwardNormals(rest, count);

  // Dense render outline (about 4px apart, at least 4 samples per sim point). Only painting uses it.
  const renderCount = Math.max(count * 4, Math.ceil(perimeter / 4));
  const denseSampled = resamplePath(restPath, renderCount + 1);
  const renderRest = new Float32Array(renderCount * 2);
  for (let k = 0; k < renderCount; k++) {
    renderRest[k * 2] = denseSampled[k * 2];
    renderRest[k * 2 + 1] = denseSampled[k * 2 + 1];
  }
  const renderNormal = outwardNormals(renderRest, renderCount);

  return {
    width,
    height,
    count,
    rest,
    normal,
    spacing: perimeter / count,
    restPath,
    renderCount,
    renderRest,
    renderNormal,
  };
}

function createSim(g: Outline): Sim {
  return {
    o: new Float32Array(g.count),
    v: new Float32Array(g.count),
    acc: new Float32Array(g.count),
    pts: new Float32Array(g.renderCount * 2),
  };
}

// Shortest index distance around the closed loop, in px of arc length.
function arcPx(i: number, at: number, count: number, spacing: number): number {
  const d = Math.abs(i - at);
  return Math.min(d, count - d) * spacing;
}

function applyPose(sim: Sim, g: Outline, at: number, amount: number) {
  const idx = (((at % 1) + 1) % 1) * g.count;
  for (let i = 0; i < g.count; i++) {
    const d = arcPx(i, idx, g.count, g.spacing);
    sim.o[i] = amount * Math.exp(-(d * d) / (2 * POSE_SIGMA * POSE_SIGMA));
    sim.v[i] = 0;
  }
}

function pluckSim(g: Outline | null, sim: Sim | null, at: number, strength: number): boolean {
  if (!g || !sim) return false;
  const idx = (((at % 1) + 1) % 1) * g.count;
  for (let i = 0; i < g.count; i++) {
    const d = arcPx(i, idx, g.count, g.spacing);
    sim.o[i] += strength * Math.exp(-(d * d) / (2 * PLUCK_SIGMA * PLUCK_SIGMA));
  }
  return true;
}

// Semi-implicit Euler in 1/240s substeps: a = -k·o + c·laplacian(o) - d·v + grab force.
function stepSim(sim: Sim, g: Outline, grab: Grab | null, p: Params, dt: number) {
  const n = g.count;
  const { o, v, acc } = sim;
  const steps = Math.max(1, Math.ceil(dt / SUBSTEP - 1e-6));
  const h = dt / steps;
  for (let s = 0; s < steps; s++) {
    for (let i = 0; i < n; i++) {
      const prev = i === 0 ? n - 1 : i - 1;
      const next = i === n - 1 ? 0 : i + 1;
      const lap = o[prev] + o[next] - 2 * o[i];
      let force = 0;
      if (grab) {
        const d = arcPx(i, grab.j, n, g.spacing);
        if (d <= GRAB_ARC) {
          const target = Math.min(p.maxStretch, Math.max(-p.maxStretch, grab.s));
          force = GRAB_GAIN * (target - o[i]) * Math.exp(-(d * d) / (2 * GRAB_SIGMA * GRAB_SIGMA));
        }
      }
      acc[i] = -p.stiffness * o[i] + p.coupling * lap - p.damping * v[i] + force;
    }
    for (let i = 0; i < n; i++) {
      v[i] += acc[i] * h;
      o[i] += v[i] * h;
    }
  }
}

function maxAbs(a: Float32Array): number {
  let m = 0;
  for (let i = 0; i < a.length; i++) {
    const x = Math.abs(a[i]);
    if (x > m) m = x;
  }
  return m;
}

function hexToRgb(hex: string): RGB {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function mixColor(a: RGB, b: RGB, t: number): string {
  const r = Math.round(a[0] + (b[0] - a[0]) * t);
  const g = Math.round(a[1] + (b[1] - a[1]) * t);
  const bl = Math.round(a[2] + (b[2] - a[2]) * t);
  return `rgb(${r},${g},${bl})`;
}

// Writes the displaced outline to both paths. Returns max |o|, used for energy and dev checks.
// Rest state paints the exact rounded rect. Otherwise the dense render outline is offset by a
// 1-D Catmull-Rom through the simulation samples, so the stroke stays smooth between them.
function paintSim(
  sim: Sim,
  g: Outline,
  maxStretch: number,
  colors: Colors,
  main: SVGPathElement | null,
  glow: SVGPathElement | null,
): number {
  const { o, pts } = sim;
  let maxO = 0;
  for (let i = 0; i < g.count; i++) {
    const a = Math.abs(o[i]);
    if (a > maxO) maxO = a;
  }
  let d: string;
  if (maxO < 0.01) {
    d = g.restPath;
  } else {
    const n = g.count;
    const m = g.renderCount;
    const ratio = n / m;
    for (let k = 0; k < m; k++) {
      const s = k * ratio;
      const i1 = Math.floor(s);
      const t = s - i1;
      const i0 = (i1 - 1 + n) % n;
      const i2 = (i1 + 1) % n;
      const i3 = (i1 + 2) % n;
      const o0 = o[i0];
      const o1 = o[i1];
      const o2 = o[i2];
      const o3 = o[i3];
      const off =
        0.5 *
        (2 * o1 +
          (-o0 + o2) * t +
          (2 * o0 - 5 * o1 + 4 * o2 - o3) * t * t +
          (-o0 + 3 * o1 - 3 * o2 + o3) * t * t * t);
      pts[k * 2] = g.renderRest[k * 2] + g.renderNormal[k * 2] * off;
      pts[k * 2 + 1] = g.renderRest[k * 2 + 1] + g.renderNormal[k * 2 + 1] * off;
    }
    const parts: string[] = new Array(m);
    for (let k = 0; k < m; k++) {
      const x = pts[k * 2].toFixed(2);
      const y = pts[k * 2 + 1].toFixed(2);
      parts[k] = k === 0 ? `M${x} ${y}` : `L${x} ${y}`;
    }
    d = `${parts.join(" ")} Z`;
  }
  const energy = Math.min(1, maxO / maxStretch);
  if (main) {
    main.setAttribute("d", d);
    main.setAttribute("stroke", mixColor(colors.rest, colors.ink, energy));
  }
  if (glow) {
    glow.setAttribute("d", d);
    glow.setAttribute("stroke-opacity", String(GLOW_ALPHA * energy));
  }
  return maxO;
}

/**
 * A frame drawn as a tensioned string. Bring the pointer near an edge to pluck it;
 * it rings back to rest. Children sit centred inside `padding`.
 * Concentric content: give children `borderRadius: radius - padding / 2`.
 */
export const ElasticFrame = forwardRef<ElasticFrameHandle, ElasticFrameProps>(function ElasticFrame(
  {
    children,
    radius = 24,
    points = 64,
    stiffness = 180,
    coupling = 900,
    damping = 14,
    pluckDistance = 36,
    maxStretch = 28,
    strokeWidth = 1.5,
    glow = true,
    glowColor,
    padding = 32,
    tone,
    attract = false,
    debugState,
    className,
  },
  ref,
) {
  const resolvedTone = useBjorkTone(tone);
  const palette = BJORK_PALETTE[resolvedTone];
  const reduce = useReducedMotion() === true;
  const rootRef = useRef<HTMLDivElement>(null);
  const mainRef = useRef<SVGPathElement>(null);
  const glowRef = useRef<SVGPathElement>(null);
  const size = useElementSize(rootRef);
  const outline = useMemo(
    () => buildOutline(size.width, size.height, radius, points),
    [size.width, size.height, radius, points],
  );

  const debugAt = debugState?.at;
  const debugAmount = debugState?.amount ?? 0;
  const glowCss = glowColor ?? palette.accent;
  const colors = useMemo<Colors>(
    () => ({
      rest: hexToRgb(palette.borderStrong),
      ink: hexToRgb(palette.accentInk),
    }),
    [palette],
  );

  const outlineRef = useRef<Outline | null>(null);
  const simRef = useRef<Sim | null>(null);
  const grabRef = useRef<Grab | null>(null);
  const boundsRef = useRef<Bounds | null>(null);
  const lastInputRef = useRef(Number.NEGATIVE_INFINITY);
  const reduceRef = useRef(reduce);
  const colorsRef = useRef<Colors>(colors);
  const wakeRef = useRef<() => void>(() => {});
  const measureRef = useRef<(() => void) | null>(null);
  const paramsRef = useRef<Params>({
    stiffness,
    coupling,
    damping,
    maxStretch,
    pluckDistance,
  });

  const frame = (dt: number): boolean => {
    const g = outlineRef.current;
    const sim = simRef.current;
    if (!g || !sim) return false;
    const p = paramsRef.current;
    const grab = grabRef.current;
    stepSim(sim, g, grab, p, dt);
    const maxO = paintSim(sim, g, p.maxStretch, colorsRef.current, mainRef.current, glowRef.current);
    if (process.env.NODE_ENV !== "production" && rootRef.current) {
      rootRef.current.dataset.maxOffset = maxO.toFixed(2);
    }
    if (!grab && maxO < IDLE_EPS && maxAbs(sim.v) < IDLE_EPS) {
      sim.o.fill(0);
      sim.v.fill(0);
      paintSim(sim, g, p.maxStretch, colorsRef.current, mainRef.current, glowRef.current);
      return false;
    }
    return true;
  };

  const loop = useVisibleLoop(rootRef, frame, { enabled: !reduce && debugAt === undefined });

  useImperativeHandle(
    ref,
    () => ({
      pluck: (at: number, strength = DEFAULT_PLUCK) => {
        if (reduceRef.current) return;
        if (pluckSim(outlineRef.current, simRef.current, at, strength)) wakeRef.current();
      },
    }),
    [],
  );

  // Keep the latest props and loop handle visible to the rAF and pointer callbacks.
  useEffect(() => {
    paramsRef.current = { stiffness, coupling, damping, maxStretch, pluckDistance };
    wakeRef.current = loop.wake;
  });

  // Geometry, reduced motion and posed state: rebuild the sim and paint once.
  useEffect(() => {
    reduceRef.current = reduce;
    outlineRef.current = outline;
    const sim = outline ? createSim(outline) : null;
    simRef.current = sim;
    grabRef.current = null;
    measureRef.current?.();
    if (outline && sim) {
      if (debugAt !== undefined) applyPose(sim, outline, debugAt, debugAmount);
      paintSim(sim, outline, paramsRef.current.maxStretch, colorsRef.current, mainRef.current, glowRef.current);
      wakeRef.current();
    }
  }, [outline, debugAt, debugAmount, reduce]);

  // Colour and glow changes repaint without resetting the string.
  useEffect(() => {
    colorsRef.current = colors;
    const g = outlineRef.current;
    const sim = simRef.current;
    if (g && sim) paintSim(sim, g, paramsRef.current.maxStretch, colors, mainRef.current, glowRef.current);
  }, [colors, glow]);

  // Pointer proximity. The pluck zone reaches 36px outside the element, so the listeners sit on
  // window. They are attached only while the frame is near the viewport.
  useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    let listening = false;

    const measure = () => {
      const r = el.getBoundingClientRect();
      const g = outlineRef.current;
      boundsRef.current = {
        left: r.left,
        top: r.top,
        sx: g && g.width ? r.width / g.width : 1,
        sy: g && g.height ? r.height / g.height : 1,
      };
    };
    measureRef.current = measure;

    const release = () => {
      if (grabRef.current) {
        grabRef.current = null;
        wakeRef.current();
      }
    };

    const onMove = (e: PointerEvent) => {
      const b = boundsRef.current;
      const g = outlineRef.current;
      const sim = simRef.current;
      if (!b || !g || !sim || reduceRef.current) return;
      const p = paramsRef.current;
      const px = (e.clientX - b.left) / b.sx;
      const py = (e.clientY - b.top) / b.sy;
      const zone = p.pluckDistance;
      if (px < -zone || py < -zone || px > g.width + zone || py > g.height + zone) {
        release();
        return;
      }
      let best = 0;
      let bestD = Number.POSITIVE_INFINITY;
      for (let j = 0; j < g.count; j++) {
        const dx = px - g.rest[j * 2];
        const dy = py - g.rest[j * 2 + 1];
        const d2 = dx * dx + dy * dy;
        if (d2 < bestD) {
          bestD = d2;
          best = j;
        }
      }
      // Signed distance along the nearest normal: positive is outside the frame.
      const s =
        (px - g.rest[best * 2]) * g.normal[best * 2] + (py - g.rest[best * 2 + 1]) * g.normal[best * 2 + 1];
      lastInputRef.current = performance.now();
      if (Math.abs(s) <= p.maxStretch + 8) {
        grabRef.current = { j: best, s };
        wakeRef.current();
      } else {
        release();
      }
    };

    // Pointer left the window: nothing is held any more.
    const onOut = (e: PointerEvent) => {
      if (!e.relatedTarget) release();
    };

    const onViewport = () => measure();

    const start = () => {
      if (listening) return;
      listening = true;
      measure();
      window.addEventListener("pointermove", onMove, { passive: true });
      window.addEventListener("pointerout", onOut, { passive: true });
      window.addEventListener("scroll", onViewport, { passive: true, capture: true });
      window.addEventListener("resize", onViewport, { passive: true });
    };

    const stop = () => {
      if (!listening) return;
      listening = false;
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerout", onOut);
      window.removeEventListener("scroll", onViewport, { capture: true });
      window.removeEventListener("resize", onViewport);
      grabRef.current = null;
    };

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry?.isIntersecting) start();
        else stop();
      },
      { rootMargin: "96px" },
    );
    observer.observe(el);

    return () => {
      observer.disconnect();
      stop();
      measureRef.current = null;
    };
  }, []);

  // Attract: a seeded pluck every 2.8s, paused while the pointer or keyboard is inside.
  useEffect(() => {
    if (!attract) return;
    const rng = mulberry32(hashString("elastic-frame"));
    const id = window.setInterval(() => {
      if (reduceRef.current) return;
      if (performance.now() - lastInputRef.current < ATTRACT_IDLE) return;
      if (pluckSim(outlineRef.current, simRef.current, rng(), ATTRACT_STRENGTH)) wakeRef.current();
    }, ATTRACT_INTERVAL);
    return () => window.clearInterval(id);
  }, [attract]);

  // Breathe only for keyboard focus. A mouse click on a child should not ripple the frame.
  const onFocus = (e: FocusEvent<HTMLDivElement>) => {
    if (!(e.target as Element).matches?.(":focus-visible")) return;
    lastInputRef.current = performance.now();
    if (reduceRef.current) return;
    const sim = simRef.current;
    if (!sim) return;
    for (let i = 0; i < sim.v.length; i++) sim.v[i] += BREATH_IMPULSE;
    wakeRef.current();
  };

  const onPointerDown = () => {
    lastInputRef.current = performance.now();
  };

  return (
    <div
      ref={rootRef}
      onFocus={onFocus}
      onPointerDown={onPointerDown}
      className={cn("relative isolate w-full", className)}
    >
      <svg
        aria-hidden="true"
        focusable="false"
        width={size.width}
        height={size.height}
        viewBox={`0 0 ${size.width} ${size.height}`}
        className="pointer-events-none absolute inset-0 overflow-visible"
      >
        {glow ? (
          <path
            ref={glowRef}
            fill="none"
            stroke={glowCss}
            strokeWidth={GLOW_WIDTH}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        ) : null}
        <path
          ref={mainRef}
          fill="none"
          stroke={palette.borderStrong}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
      <div className="relative flex h-full w-full items-center justify-center" style={{ padding }}>
        {children}
      </div>
    </div>
  );
});

/** Pulls the frame from outside through a ref: `pluck(frameRef, 0.4, 26)`. */
export function pluck(
  target: { current: ElasticFrameHandle | null },
  at: number,
  strength?: number,
): void {
  target.current?.pluck(at, strength);
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export type BjorkTone = "dark" | "light";

// Canvas, WebGL and SVG attribute colours. DOM code uses the CSS tokens with these as fallbacks.
export const BJORK_PALETTE = {
  dark: {
    bg: "#050505", stage: "#111111", surface: "#121212", raised: "#161616", active: "#202020",
    border: "#232323", borderStrong: "#343434",
    text: "#ededed", textMedium: "rgba(237,237,237,0.72)", textMuted: "rgba(237,237,237,0.52)",
    textSoft: "rgba(237,237,237,0.36)", textFaint: "rgba(237,237,237,0.22)", hair: "rgba(237,237,237,0.12)",
    accent: "#ec5c13", accentInk: "#ec5c13", accentFill: "#b84a12", accentSoft: "rgba(236,92,19,0.12)", accentMuted: "rgba(236,92,19,0.24)",
    accentFg: "#fff2ea", success: "#4cc38a", warning: "#f2b544", error: "#ff5c4d",
  },
  light: {
    bg: "#f7f5ef", stage: "#f7f5ef", surface: "#fffcf6", raised: "#f5efe3", active: "#efe7d8",
    border: "#eee6db", borderStrong: "#e1d7c8",
    text: "#171717", textMedium: "rgba(23,23,23,0.72)", textMuted: "rgba(23,23,23,0.52)",
    textSoft: "rgba(23,23,23,0.36)", textFaint: "rgba(23,23,23,0.22)", hair: "rgba(23,23,23,0.10)",
    accent: "#ec7d43", accentInk: "#b4531f", accentFill: "#ec7d43", accentSoft: "rgba(236,125,67,0.10)", accentMuted: "rgba(236,125,67,0.20)",
    accentFg: "#3f2112", success: "#1f8a55", warning: "#a86b00", error: "#c8361f",
  },
} as const;

"use client";

import { useSyncExternalStore } from "react";
import { useTheme } from "next-themes";
import type { BjorkTone } from "./palette";

const subscribeNoop = () => () => {};
const getMounted = () => true;
const getServerMounted = () => false;

/**
 * Resolves the tone for a component. An explicit `tone` always wins.
 * Otherwise it follows next-themes' resolved theme, but only after mount,
 * so the server render and first client render agree on dark.
 */
export function useBjorkTone(tone?: BjorkTone): BjorkTone {
  const { resolvedTheme } = useTheme();
  const mounted = useSyncExternalStore(subscribeNoop, getMounted, getServerMounted);
  if (tone) return tone;
  if (!mounted) return "dark";
  return resolvedTheme === "light" ? "light" : "dark";
}

"use client";

import { useCallback, useEffect, useMemo, useRef, type RefObject } from "react";

export interface VisibleLoopOptions {
  enabled?: boolean;
  fpsCap?: number;
  rootMargin?: string;
}

/**
 * Runs `frame(dt, t)` on requestAnimationFrame while the element is near the viewport,
 * the tab is visible and `enabled` is not false. Return `false` from `frame` to go idle
 * until `wake()` is called. Writes `data-loop` on the element: running, idle or paused.
 */
export function useVisibleLoop(
  ref: RefObject<HTMLElement | null>,
  frame: (dt: number, t: number) => boolean | void,
  opts?: VisibleLoopOptions,
): { wake: () => void } {
  const enabled = opts?.enabled !== false;
  const fpsCap = opts?.fpsCap ?? 0;
  const rootMargin = opts?.rootMargin ?? "96px";

  const frameRef = useRef(frame);
  useEffect(() => {
    frameRef.current = frame;
  }, [frame]);

  const wakeRef = useRef<() => void>(() => {});
  const wake = useCallback(() => wakeRef.current(), []);

  useEffect(() => {
    const el = ref.current;
    if (!el || typeof window === "undefined") return;

    let wants = true; // false once the frame callback returns false
    let inView = false;
    let raf = 0;
    let last = 0;
    let t = 0;
    const minFrame = fpsCap > 0 ? 1000 / fpsCap : 0;

    const canRun = () => enabled && inView && document.visibilityState === "visible";
    const stop = () => {
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
    };

    const update = () => {
      if (!enabled) {
        stop();
        el.dataset.loop = "paused";
        return;
      }
      if (!wants) {
        stop();
        el.dataset.loop = "idle";
        return;
      }
      if (!canRun()) {
        stop();
        el.dataset.loop = "paused";
        return;
      }
      el.dataset.loop = "running";
      if (!raf) {
        last = performance.now();
        raf = requestAnimationFrame(tick);
      }
    };

    const tick = (now: number) => {
      raf = 0;
      if (!canRun() || !wants) {
        update();
        return;
      }
      const elapsed = now - last;
      if (minFrame && elapsed < minFrame - 0.5) {
        raf = requestAnimationFrame(tick);
        return;
      }
      last = now;
      const dt = Math.min(0.05, Math.max(0, elapsed / 1000));
      t += dt;
      const keep = frameRef.current(dt, t);
      if (keep === false) {
        wants = false;
        update();
        return;
      }
      raf = requestAnimationFrame(tick);
    };

    const observer = new IntersectionObserver(
      ([entry]) => {
        inView = entry.isIntersecting;
        update();
      },
      { rootMargin },
    );
    observer.observe(el);

    const onVisibility = () => update();
    document.addEventListener("visibilitychange", onVisibility);

    wakeRef.current = () => {
      wants = true;
      update();
    };

    update();

    return () => {
      stop();
      observer.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      wakeRef.current = () => {};
    };
  }, [ref, enabled, fpsCap, rootMargin]);

  return useMemo(() => ({ wake }), [wake]);
}

// matchMedia based check. False on the server.
export function isCoarsePointer(): boolean {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return false;
  return window.matchMedia("(pointer: coarse)").matches;
}

"use client";

import { useEffect, useState, type RefObject } from "react";
import { isCoarsePointer } from "./loop";

// Caps DPR at 1.5 on coarse pointers and 2 otherwise.
export function defaultMaxDpr(): number {
  return isCoarsePointer() ? 1.5 : 2;
}

// Sets the backing size for a CSS box and returns the DPR used.
export function sizeCanvas(
  canvas: HTMLCanvasElement,
  cssW: number,
  cssH: number,
  maxDpr: number = defaultMaxDpr(),
): number {
  const dpr = Math.min(typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1, maxDpr);
  canvas.width = Math.max(1, Math.round(cssW * dpr));
  canvas.height = Math.max(1, Math.round(cssH * dpr));
  canvas.style.width = `${cssW}px`;
  canvas.style.height = `${cssH}px`;
  return dpr;
}

// Rounded size of an element, kept current with a ResizeObserver.
export function useElementSize(ref: RefObject<HTMLElement | null>): { width: number; height: number } {
  const [size, setSize] = useState({ width: 0, height: 0 });

  useEffect(() => {
    const el = ref.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver((entries) => {
      const box = entries[0]?.contentRect;
      if (!box) return;
      const width = Math.round(box.width);
      const height = Math.round(box.height);
      setSize((prev) => (prev.width === width && prev.height === height ? prev : { width, height }));
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  return size;
}

// SVG path helpers. Path sampling needs the DOM, so it returns zeros on the server.

const resampleCache = new Map<string, Float32Array>();

// Interleaved x,y points at equal arc length along `d`, including both endpoints.
export function resamplePath(
  d: string,
  count: number,
  viewBox?: [number, number, number, number],
): Float32Array {
  if (typeof document === "undefined") return new Float32Array(count * 2);
  const key = `${d}|${count}|${viewBox ? viewBox.join(",") : ""}`;
  const cached = resampleCache.get(key);
  if (cached) return cached;

  const svgNS = "http://www.w3.org/2000/svg";
  const svg = document.createElementNS(svgNS, "svg");
  svg.setAttribute("width", "0");
  svg.setAttribute("height", "0");
  svg.setAttribute("aria-hidden", "true");
  svg.style.position = "absolute";
  svg.style.visibility = "hidden";
  if (viewBox) svg.setAttribute("viewBox", viewBox.join(" "));
  const path = document.createElementNS(svgNS, "path");
  path.setAttribute("d", d);
  svg.appendChild(path);
  document.body.appendChild(svg);

  const out = new Float32Array(count * 2);
  try {
    const total = path.getTotalLength();
    for (let i = 0; i < count; i++) {
      const at = count === 1 ? 0 : (i / (count - 1)) * total;
      const p = path.getPointAtLength(at);
      out[i * 2] = p.x;
      out[i * 2 + 1] = p.y;
    }
  } finally {
    svg.remove();
  }
  resampleCache.set(key, out);
  return out;
}

// Catmull-Rom through interleaved x,y points, converted to cubic beziers. Returns a path `d`.
export function catmullRomToBezier(points: Float32Array, closed: boolean): string {
  const n = Math.floor(points.length / 2);
  if (n === 0) return "";
  const P = (i: number) => {
    let idx = i;
    if (closed) idx = ((i % n) + n) % n;
    else idx = Math.min(n - 1, Math.max(0, i));
    return [points[idx * 2], points[idx * 2 + 1]] as const;
  };
  const f = (v: number) => v.toFixed(2);
  let d = `M${f(points[0])} ${f(points[1])}`;
  const segments = closed ? n : n - 1;
  for (let i = 0; i < segments; i++) {
    const p0 = P(i - 1);
    const p1 = P(i);
    const p2 = P(i + 1);
    const p3 = P(i + 2);
    const c1x = p1[0] + (p2[0] - p0[0]) / 6;
    const c1y = p1[1] + (p2[1] - p0[1]) / 6;
    const c2x = p2[0] - (p3[0] - p1[0]) / 6;
    const c2y = p2[1] - (p3[1] - p1[1]) / 6;
    d += ` C${f(c1x)} ${f(c1y)} ${f(c2x)} ${f(c2y)} ${f(p2[0])} ${f(p2[1])}`;
  }
  if (closed) d += " Z";
  return d;
}

// Seeded randomness and noise. Deterministic for a given seed, so previews and tests repeat.

// Small fast PRNG. Returns floats in [0, 1).
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// FNV-1a 32-bit.
export function hashString(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

// Integer lattice hash to [-1, 1].
function latticeHash(seed: number, x: number, y = 0): number {
  let h = Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263) ^ Math.imul(seed | 0, 2246822519);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return ((h >>> 0) / 4294967295) * 2 - 1;
}

function smooth(t: number): number {
  return t * t * (3 - 2 * t);
}

export function valueNoise1D(seed: number): (x: number) => number {
  return (x: number) => {
    const i = Math.floor(x);
    const f = x - i;
    const a = latticeHash(seed, i);
    const b = latticeHash(seed, i + 1);
    return a + (b - a) * smooth(f);
  };
}

export function fbm1D(seed: number, octaves = 3): (x: number) => number {
  const layers = Array.from({ length: octaves }, (_, o) => valueNoise1D(seed + o * 101));
  let norm = 0;
  for (let o = 0; o < octaves; o++) norm += 0.5 ** o;
  return (x: number) => {
    let sum = 0;
    let amp = 1;
    let freq = 1;
    for (let o = 0; o < octaves; o++) {
      sum += amp * layers[o](x * freq);
      amp *= 0.5;
      freq *= 2;
    }
    return sum / norm;
  };
}

export function valueNoise2D(seed: number): (x: number, y: number) => number {
  return (x: number, y: number) => {
    const xi = Math.floor(x);
    const yi = Math.floor(y);
    const fx = smooth(x - xi);
    const fy = smooth(y - yi);
    const a = latticeHash(seed, xi, yi);
    const b = latticeHash(seed, xi + 1, yi);
    const c = latticeHash(seed, xi, yi + 1);
    const d = latticeHash(seed, xi + 1, yi + 1);
    const top = a + (b - a) * fx;
    const bottom = c + (d - c) * fx;
    return top + (bottom - top) * fy;
  };
}
